    if x == 0:
        return "0"

    sign = 1 if x > 0 else -1
    x = abs(x)

    num_digits = len(str(x))
    actual_shift = shift % num_digits

    if actual_shift == 0:
        return str(x)

    shifted_num = int(str(x)[-actual_shift:] + str(x)[:-actual_shift])

